import { integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';

export const browserAuthority = sqliteTable('browser_authority', {
  singleton: integer().primaryKey(),
  accountId: text('account_id'),
  generation: text().notNull(),
  operationId: text('operation_id'),
  phase: text({ enum: ['ready', 'changing'] }).notNull(),
});

export const browserCredentials = sqliteTable('browser_credentials', {
  digest: text().primaryKey(),
  scope: text().notNull(),
  accountId: text('account_id'),
  generation: text().notNull(),
  kind: text({ enum: ['session', 'launch'] }).notNull(),
  expiresAt: integer('expires_at').notNull(),
});
